CREATE OR REPLACE FUNCTION public.apply_company_discovery_v2(p_job_id uuid, p_canonical_name text DEFAULT NULL::text, p_domain text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_sector_raw text DEFAULT NULL::text, p_subsectors text[] DEFAULT NULL::text[], p_description text DEFAULT NULL::text, p_logo_source_url text DEFAULT NULL::text, p_logo_confidence numeric DEFAULT NULL::numeric, p_branding jsonb DEFAULT '{}'::jsonb, p_sources jsonb DEFAULT '[]'::jsonb, p_provider text DEFAULT 'firecrawl'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_job public.enrichment_jobs%rowtype;
  v_sector jsonb;
  v_sector_code text;
  v_sector_score numeric;
  v_score numeric := 0;
  v_status text;
  v_source_count integer := 0;
  v_reference_count integer := 0;
  v_source jsonb;
  v_is_official boolean := false;
  v_logo_conf numeric;
begin
  select *
  into v_job
  from public.enrichment_jobs
  where id = p_job_id
  for update;

  if not found then
    raise exception 'enrichment job not found: %', p_job_id;
  end if;

  if p_logo_confidence is not null and (p_logo_confidence < 0 or p_logo_confidence > 1) then
    raise exception 'logo confidence must be between 0 and 1';
  end if;

  if jsonb_typeof(coalesce(p_sources, '[]'::jsonb)) <> 'array' then
    raise exception 'sources must be a JSON array';
  end if;

  v_sector := public.normalize_sector_v1(p_sector_raw, p_subsectors);
  v_sector_code := v_sector->>'code';
  v_sector_score := coalesce((v_sector->>'score')::numeric, 0);

  if nullif(trim(p_domain), '') is not null and nullif(trim(p_website), '') is not null then
    v_score := v_score + 0.20;
  elsif nullif(trim(p_domain), '') is not null or nullif(trim(p_website), '') is not null then
    v_score := v_score + 0.10;
  end if;

  if nullif(trim(p_canonical_name), '') is not null then
    v_score := v_score + 0.10;
  end if;

  if v_sector_code <> 'other' then
    v_score := v_score + (0.25 * greatest(0, least(1, v_sector_score)));
  end if;

  v_logo_conf := coalesce(p_logo_confidence, case when p_logo_source_url is not null then 0.7 else 0 end);
  if nullif(trim(p_logo_source_url), '') is not null then
    v_score := v_score + (0.15 * greatest(0, least(1, v_logo_conf)));
  end if;

  if nullif(trim(p_description), '') is not null then
    v_score := v_score + 0.10;
  end if;

  for v_source in
    select value from jsonb_array_elements(coalesce(p_sources, '[]'::jsonb))
  loop
    v_source_count := v_source_count + 1;
    v_is_official := v_is_official or coalesce((v_source->>'is_official')::boolean, false);

    insert into public.company_discovery_sources (
      company_id,
      enrichment_job_id,
      source_type,
      provider,
      source_url,
      is_official,
      confidence,
      extracted
    )
    values (
      v_job.company_id,
      p_job_id,
      coalesce(nullif(v_source->>'source_type',''), 'other'),
      coalesce(nullif(v_source->>'provider',''), p_provider),
      nullif(v_source->>'source_url',''),
      coalesce((v_source->>'is_official')::boolean, false),
      case
        when nullif(v_source->>'confidence','') is null then null
        else greatest(0, least(1, (v_source->>'confidence')::numeric))
      end,
      coalesce(v_source->'extracted', '{}'::jsonb)
    );
  end loop;

  if v_source_count > 0 then
    v_score := v_score + least(0.10, v_source_count * 0.025);
  end if;

  if v_is_official then
    v_score := v_score + 0.10;
  end if;

  v_score := greatest(0, least(1, v_score));

  if v_score >= 0.80 and v_sector_code <> 'other' and v_is_official then
    v_status := 'enriched';
  elsif v_score >= 0.55 then
    v_status := 'partial';
  else
    v_status := 'needs_review';
  end if;

  update public.companies
  set
    name = coalesce(nullif(trim(p_canonical_name), ''), name),
    domain = coalesce(nullif(trim(p_domain), ''), domain),
    website = coalesce(nullif(trim(p_website), ''), website),
    sector = case when v_sector_code <> 'other' then v_sector_code else sector end,
    subsector = coalesce(nullif(array_to_string(p_subsectors, ' / '), ''), subsector),
    logo_url = coalesce(nullif(trim(p_logo_source_url), ''), logo_url),
    enrichment_status = v_status,
    enrichment_confidence = v_score,
    enrichment_data =
      coalesce(enrichment_data, '{}'::jsonb) ||
      jsonb_build_object(
        'provider', p_provider,
        'canonical_name', p_canonical_name,
        'description', p_description,
        'sector_raw', p_sector_raw,
        'sector_normalized', v_sector,
        'subsectors', coalesce(to_jsonb(p_subsectors), '[]'::jsonb),
        'branding', coalesce(p_branding, '{}'::jsonb),
        'source_count', v_source_count
      ),
    updated_at = now()
  where id = v_job.company_id;

  if nullif(trim(p_logo_source_url), '') is not null then
    update public.company_brand_assets
    set is_primary = false, updated_at = now()
    where company_id = v_job.company_id
      and asset_type = 'logo'
      and is_primary = true;

    insert into public.company_brand_assets (
      company_id,
      asset_type,
      source_url,
      confidence,
      status,
      is_primary,
      metadata
    )
    values (
      v_job.company_id,
      'logo',
      p_logo_source_url,
      v_logo_conf,
      'pending_copy',
      true,
      jsonb_build_object(
        'provider', p_provider,
        'discovered_from_job', p_job_id
      )
    );
  end if;

  if coalesce(p_branding, '{}'::jsonb) <> '{}'::jsonb then
    insert into public.company_brand_assets (
      company_id,
      asset_type,
      confidence,
      status,
      is_primary,
      metadata
    )
    values (
      v_job.company_id,
      'brand_palette',
      coalesce((p_branding#>>'{confidence,overall}')::numeric, v_score),
      'stored',
      true,
      p_branding
    );
  end if;

  update public.enrichment_jobs
  set
    provider = p_provider,
    status = case when v_status = 'enriched' then 'completed' else 'needs_review' end,
    output = jsonb_build_object(
      'canonical_name', p_canonical_name,
      'domain', p_domain,
      'website', p_website,
      'sector', v_sector_code,
      'sector_details', v_sector,
      'subsectors', coalesce(to_jsonb(p_subsectors), '[]'::jsonb),
      'description', p_description,
      'logo_source_url', p_logo_source_url,
      'branding', coalesce(p_branding, '{}'::jsonb),
      'confidence', v_score,
      'enrichment_status', v_status,
      'source_count', v_source_count
    ),
    error_message = null,
    locked_by = null,
    locked_until = null,
    completed_at = case when v_status = 'enriched' then now() else completed_at end,
    updated_at = now()
  where id = p_job_id;

  if v_job.proposal_id is not null then
    delete from public.proposal_references
    where proposal_id = v_job.proposal_id;

    if v_sector_code <> 'other' then
      with selected as (
        select id,
               row_number() over (order by priority desc, company_name asc) as pos
        from public.reference_clients
        where active = true
          and approved_for_marketing = true
          and sector = v_sector_code
        order by priority desc, company_name asc
        limit 6
      )
      insert into public.proposal_references (
        proposal_id, reference_client_id, position
      )
      select v_job.proposal_id, id, pos
      from selected
      on conflict do nothing;

      get diagnostics v_reference_count = row_count;
    end if;

    update public.proposals
    set
      proposal_snapshot =
        proposal_snapshot ||
        jsonb_build_object(
          'company_enrichment',
          jsonb_build_object(
            'canonical_name', p_canonical_name,
            'domain', p_domain,
            'website', p_website,
            'sector', v_sector_code,
            'sector_details', v_sector,
            'subsectors', coalesce(to_jsonb(p_subsectors), '[]'::jsonb),
            'description', p_description,
            'logo_url', p_logo_source_url,
            'branding', coalesce(p_branding, '{}'::jsonb),
            'confidence', v_score,
            'status', v_status
          ),
          'reference_count',
          v_reference_count
        ),
      updated_at = now()
    where id = v_job.proposal_id;

    if v_status = 'enriched' then
      update public.render_jobs
      set
        status = 'pending',
        input = input || jsonb_build_object(
          'enrichment_job_id', p_job_id,
          'sector', v_sector_code,
          'reference_count', v_reference_count,
          'company_confidence', v_score
        ),
        updated_at = now()
      where proposal_id = v_job.proposal_id
        and status = 'waiting';

      update public.proposals
      set status = 'rendering', updated_at = now()
      where id = v_job.proposal_id;
    else
      update public.proposals
      set status = 'enriching', updated_at = now()
      where id = v_job.proposal_id;
    end if;
  end if;

  return jsonb_build_object(
    'job_id', p_job_id,
    'company_id', v_job.company_id,
    'proposal_id', v_job.proposal_id,
    'sector', v_sector_code,
    'sector_details', v_sector,
    'confidence', v_score,
    'enrichment_status', v_status,
    'source_count', v_source_count,
    'reference_count', v_reference_count,
    'render_released', v_status = 'enriched' and v_job.proposal_id is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_proposal_v1(p_fleet_size integer, p_vehicle_profile_code text DEFAULT 'rodotrem_9_eixos'::text, p_financial_version text DEFAULT NULL::text, p_monthly_km numeric DEFAULT NULL::numeric, p_consumption_km_l numeric DEFAULT NULL::numeric, p_diesel_price numeric DEFAULT NULL::numeric, p_tire_price numeric DEFAULT NULL::numeric, p_tire_replacement_factor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_profile public.vehicle_profiles%rowtype;
  v_fin public.financial_parameter_sets%rowtype;

  v_monthly_km numeric;
  v_consumption numeric;
  v_diesel_price numeric;
  v_tire_price numeric;
  v_replacement_factor numeric;

  v_total_tires integer;
  v_total_equalizers numeric;
  v_total_supports numeric;
  v_investment numeric;
  v_protected_assets numeric;
  v_annual_diesel_liters numeric;
  v_annual_diesel_cost numeric;
  v_fuel_savings_min numeric;
  v_fuel_savings_default numeric;
  v_fuel_savings_max numeric;
  v_tire_savings numeric;
  v_total_savings numeric;
  v_roi numeric;
  v_payback numeric;

  v_missing text[] := array[]::text[];
begin
  if p_fleet_size is null or p_fleet_size <= 0 then
    raise exception 'fleet_size must be greater than zero';
  end if;

  select *
  into v_profile
  from public.vehicle_profiles
  where code = p_vehicle_profile_code
    and active = true
  limit 1;

  if not found then
    raise exception 'vehicle profile not found: %', p_vehicle_profile_code;
  end if;

  if p_financial_version is null then
    select *
    into v_fin
    from public.financial_parameter_sets
    where active = true
      and valid_from <= current_date
      and (valid_until is null or valid_until >= current_date)
    order by valid_from desc, created_at desc
    limit 1;
  else
    select *
    into v_fin
    from public.financial_parameter_sets
    where version = p_financial_version
    limit 1;
  end if;

  if v_fin.id is null then
    raise exception 'financial parameter set not found';
  end if;

  v_monthly_km := coalesce(p_monthly_km, v_profile.avg_monthly_km);
  v_consumption := coalesce(p_consumption_km_l, v_profile.avg_consumption_km_l);
  v_diesel_price := coalesce(p_diesel_price, v_fin.diesel_price);
  v_tire_price := coalesce(p_tire_price, v_fin.tire_price, v_profile.default_tire_price);
  v_replacement_factor := coalesce(p_tire_replacement_factor, v_fin.annual_tire_replacement_factor);

  v_total_tires := p_fleet_size * v_profile.tires_per_vehicle;

  if v_profile.equalizers_per_vehicle is not null then
    v_total_equalizers := p_fleet_size * v_profile.equalizers_per_vehicle;
  else
    v_missing := array_append(v_missing, 'equalizers_per_vehicle');
  end if;

  if v_profile.supports_per_vehicle is not null then
    v_total_supports := p_fleet_size * v_profile.supports_per_vehicle;
  else
    v_missing := array_append(v_missing, 'supports_per_vehicle');
  end if;

  if v_tire_price is not null then
    v_protected_assets := v_total_tires * v_tire_price;
  else
    v_missing := array_append(v_missing, 'tire_price');
  end if;

  if v_total_equalizers is not null
     and v_total_supports is not null
     and v_fin.equalizer_unit_price is not null
     and v_fin.support_unit_price is not null
  then
    v_investment :=
      (v_total_equalizers * v_fin.equalizer_unit_price)
      + (v_total_supports * v_fin.support_unit_price)
      + coalesce(v_fin.installation_cost, 0);
  else
    if v_fin.equalizer_unit_price is null then
      v_missing := array_append(v_missing, 'equalizer_unit_price');
    end if;
    if v_fin.support_unit_price is null then
      v_missing := array_append(v_missing, 'support_unit_price');
    end if;
  end if;

  if v_monthly_km is null then
    v_missing := array_append(v_missing, 'avg_monthly_km');
  end if;
  if v_consumption is null then
    v_missing := array_append(v_missing, 'avg_consumption_km_l');
  end if;
  if v_diesel_price is null then
    v_missing := array_append(v_missing, 'diesel_price');
  end if;

  if v_monthly_km is not null
     and v_consumption is not null
     and v_diesel_price is not null
  then
    v_annual_diesel_liters := (p_fleet_size * v_monthly_km * 12) / v_consumption;
    v_annual_diesel_cost := v_annual_diesel_liters * v_diesel_price;

    v_fuel_savings_min := v_annual_diesel_cost * v_fin.diesel_savings_min;
    v_fuel_savings_default := v_annual_diesel_cost * v_fin.diesel_savings_default;
    v_fuel_savings_max := v_annual_diesel_cost * v_fin.diesel_savings_max;
  end if;

  if v_tire_price is not null and v_replacement_factor is not null then
    v_tire_savings :=
      v_total_tires
      * v_tire_price
      * v_replacement_factor
      * v_fin.tire_life_gain;
  else
    if v_replacement_factor is null then
      v_missing := array_append(v_missing, 'annual_tire_replacement_factor');
    end if;
  end if;

  if v_fuel_savings_default is not null and v_tire_savings is not null then
    v_total_savings := v_fuel_savings_default + v_tire_savings;
  end if;

  if v_total_savings is not null and v_investment is not null and v_investment > 0 then
    v_roi :=
      ((v_total_savings - coalesce(v_fin.annual_operational_cost, 0)) / v_investment) * 100;

    if v_total_savings > 0 then
      v_payback := v_investment / (v_total_savings / 12);
    end if;
  end if;

  select array_agg(distinct x order by x)
  into v_missing
  from unnest(v_missing) as t(x);

  return jsonb_build_object(
    'engine', jsonb_build_object(
      'name', 'og-proposal-calculator',
      'version', '1.0.0',
      'status', case when coalesce(array_length(v_missing, 1), 0) = 0 then 'ready' else 'needs_configuration' end
    ),
    'input', jsonb_build_object(
      'fleet_size', p_fleet_size,
      'vehicle_profile_code', p_vehicle_profile_code,
      'financial_version', v_fin.version
    ),
    'fleet', jsonb_build_object(
      'vehicles', p_fleet_size,
      'tires_per_vehicle', v_profile.tires_per_vehicle,
      'total_tires', v_total_tires,
      'equalizers_per_vehicle', v_profile.equalizers_per_vehicle,
      'total_equalizers', v_total_equalizers,
      'supports_per_vehicle', v_profile.supports_per_vehicle,
      'total_supports', v_total_supports
    ),
    'assumptions', jsonb_build_object(
      'monthly_km', v_monthly_km,
      'consumption_km_l', v_consumption,
      'diesel_price', v_diesel_price,
      'tire_price', v_tire_price,
      'annual_tire_replacement_factor', v_replacement_factor,
      'tire_life_gain', v_fin.tire_life_gain,
      'diesel_savings_min', v_fin.diesel_savings_min,
      'diesel_savings_default', v_fin.diesel_savings_default,
      'diesel_savings_max', v_fin.diesel_savings_max
    ),
    'investment', jsonb_build_object(
      'total', v_investment
    ),
    'roi', jsonb_build_object(
      'protected_asset_value', v_protected_assets,
      'annual_diesel_liters', v_annual_diesel_liters,
      'annual_diesel_cost', v_annual_diesel_cost,
      'annual_fuel_savings_min', v_fuel_savings_min,
      'annual_fuel_savings_default', v_fuel_savings_default,
      'annual_fuel_savings_max', v_fuel_savings_max,
      'annual_tire_savings', v_tire_savings,
      'annual_total_savings', v_total_savings,
      'roi_percent', v_roi,
      'payback_months', v_payback
    ),
    'missing_configuration', coalesce(to_jsonb(v_missing), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_proposal_v2(p_fleet_size integer, p_vehicle_profile_code text DEFAULT 'rodotrem_9_eixos'::text, p_financial_version text DEFAULT NULL::text, p_monthly_km numeric DEFAULT NULL::numeric, p_consumption_km_l numeric DEFAULT NULL::numeric, p_diesel_price numeric DEFAULT NULL::numeric, p_monthly_diesel_cost_per_vehicle numeric DEFAULT NULL::numeric, p_tire_price numeric DEFAULT NULL::numeric, p_tire_replacement_factor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_profile public.vehicle_profiles%rowtype;
  v_fin public.financial_parameter_sets%rowtype;

  v_monthly_km numeric;
  v_consumption numeric;
  v_diesel_price numeric;
  v_tire_price numeric;
  v_replacement_factor numeric;

  v_total_tires integer;
  v_total_equalizers numeric;
  v_total_supports numeric;
  v_investment numeric;
  v_protected_assets numeric;
  v_annual_diesel_liters numeric;
  v_annual_diesel_cost numeric;
  v_fuel_savings_min numeric;
  v_fuel_savings_default numeric;
  v_fuel_savings_max numeric;
  v_tire_savings numeric;
  v_total_savings numeric;
  v_roi numeric;
  v_payback numeric;

  v_blockers text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
  v_status text;
begin
  if p_fleet_size is null or p_fleet_size <= 0 then
    raise exception 'fleet_size must be greater than zero';
  end if;

  select *
  into v_profile
  from public.vehicle_profiles
  where code = p_vehicle_profile_code
    and active = true
  limit 1;

  if not found then
    raise exception 'vehicle profile not found: %', p_vehicle_profile_code;
  end if;

  if p_financial_version is null then
    select *
    into v_fin
    from public.financial_parameter_sets
    where active = true
      and valid_from <= current_date
      and (valid_until is null or valid_until >= current_date)
    order by valid_from desc, created_at desc
    limit 1;
  else
    select *
    into v_fin
    from public.financial_parameter_sets
    where version = p_financial_version
    limit 1;
  end if;

  if v_fin.id is null then
    raise exception 'financial parameter set not found';
  end if;

  v_monthly_km := coalesce(p_monthly_km, v_profile.avg_monthly_km);
  v_consumption := coalesce(p_consumption_km_l, v_profile.avg_consumption_km_l);
  v_diesel_price := coalesce(p_diesel_price, v_fin.diesel_price);
  v_tire_price := coalesce(p_tire_price, v_fin.tire_price, v_profile.default_tire_price);
  v_replacement_factor := coalesce(
    p_tire_replacement_factor,
    v_fin.annual_tire_replacement_factor,
    case when v_fin.tire_cycle_months is not null then 12.0 / v_fin.tire_cycle_months else null end
  );

  v_total_tires := p_fleet_size * v_profile.tires_per_vehicle;

  if v_profile.equalizers_per_vehicle is not null then
    v_total_equalizers := p_fleet_size * v_profile.equalizers_per_vehicle;
  else
    v_warnings := array_append(v_warnings, 'equalizers_per_vehicle_missing');
  end if;

  if v_profile.supports_per_vehicle is not null then
    v_total_supports := p_fleet_size * v_profile.supports_per_vehicle;
  else
    v_warnings := array_append(v_warnings, 'supports_per_vehicle_missing');
  end if;

  if v_tire_price is not null then
    v_protected_assets := v_total_tires * v_tire_price;
  else
    v_blockers := array_append(v_blockers, 'tire_price');
  end if;

  if v_fin.package_price_per_vehicle is not null then
    v_investment :=
      (p_fleet_size * v_fin.package_price_per_vehicle)
      + coalesce(v_fin.installation_cost, 0);
  elsif v_total_equalizers is not null
     and v_total_supports is not null
     and v_fin.equalizer_unit_price is not null
     and v_fin.support_unit_price is not null
  then
    v_investment :=
      (v_total_equalizers * v_fin.equalizer_unit_price)
      + (v_total_supports * v_fin.support_unit_price)
      + coalesce(v_fin.installation_cost, 0);
  else
    v_blockers := array_append(v_blockers, 'investment_pricing');
  end if;

  if v_tire_price is not null and v_replacement_factor is not null then
    v_tire_savings :=
      v_total_tires
      * v_tire_price
      * v_replacement_factor
      * v_fin.tire_life_gain;
  else
    if v_replacement_factor is null then
      v_blockers := array_append(v_blockers, 'tire_replacement_factor');
    end if;
  end if;

  if p_monthly_diesel_cost_per_vehicle is not null then
    if p_monthly_diesel_cost_per_vehicle < 0 then
      raise exception 'monthly_diesel_cost_per_vehicle cannot be negative';
    end if;
    v_annual_diesel_cost := p_fleet_size * p_monthly_diesel_cost_per_vehicle * 12;
  elsif v_monthly_km is not null
     and v_consumption is not null
     and v_diesel_price is not null
  then
    v_annual_diesel_liters := (p_fleet_size * v_monthly_km * 12) / v_consumption;
    v_annual_diesel_cost := v_annual_diesel_liters * v_diesel_price;
  else
    v_warnings := array_append(v_warnings, 'diesel_cost_base_missing');
  end if;

  if v_annual_diesel_cost is not null then
    v_fuel_savings_min := v_annual_diesel_cost * v_fin.diesel_savings_min;
    v_fuel_savings_default := v_annual_diesel_cost * v_fin.diesel_savings_default;
    v_fuel_savings_max := v_annual_diesel_cost * v_fin.diesel_savings_max;
  end if;

  v_total_savings := coalesce(v_tire_savings, 0) + coalesce(v_fuel_savings_default, 0);

  if v_investment is not null and v_investment > 0 and v_total_savings > 0 then
    v_roi :=
      ((v_total_savings - coalesce(v_fin.annual_operational_cost, 0)) / v_investment) * 100;
    v_payback := v_investment / (v_total_savings / 12);
  end if;

  if coalesce(array_length(v_blockers, 1), 0) > 0 then
    v_status := 'needs_configuration';
  elsif v_annual_diesel_cost is null then
    v_status := 'ready_partial';
  else
    v_status := 'ready';
  end if;

  return jsonb_build_object(
    'engine', jsonb_build_object(
      'name', 'og-proposal-calculator',
      'version', '2.0.0',
      'status', v_status,
      'calculation_scope',
        case
          when v_status = 'ready' then 'tires_and_fuel'
          when v_status = 'ready_partial' then 'tires_only'
          else 'incomplete'
        end
    ),
    'input', jsonb_build_object(
      'fleet_size', p_fleet_size,
      'vehicle_profile_code', p_vehicle_profile_code,
      'financial_version', v_fin.version
    ),
    'fleet', jsonb_build_object(
      'vehicles', p_fleet_size,
      'tires_per_vehicle', v_profile.tires_per_vehicle,
      'total_tires', v_total_tires,
      'equalizers_per_vehicle', v_profile.equalizers_per_vehicle,
      'total_equalizers', v_total_equalizers,
      'supports_per_vehicle', v_profile.supports_per_vehicle,
      'total_supports', v_total_supports
    ),
    'assumptions', jsonb_build_object(
      'monthly_km', v_monthly_km,
      'consumption_km_l', v_consumption,
      'diesel_price', v_diesel_price,
      'monthly_diesel_cost_per_vehicle', p_monthly_diesel_cost_per_vehicle,
      'tire_price', v_tire_price,
      'tire_cycle_months', v_fin.tire_cycle_months,
      'annual_tire_replacement_factor', v_replacement_factor,
      'tire_life_gain', v_fin.tire_life_gain,
      'diesel_savings_min', v_fin.diesel_savings_min,
      'diesel_savings_default', v_fin.diesel_savings_default,
      'diesel_savings_max', v_fin.diesel_savings_max,
      'package_price_per_vehicle', v_fin.package_price_per_vehicle
    ),
    'investment', jsonb_build_object(
      'total', v_investment,
      'package_price_per_vehicle', v_fin.package_price_per_vehicle
    ),
    'roi', jsonb_build_object(
      'protected_asset_value', v_protected_assets,
      'annual_diesel_liters', v_annual_diesel_liters,
      'annual_diesel_cost', v_annual_diesel_cost,
      'annual_fuel_savings_min', v_fuel_savings_min,
      'annual_fuel_savings_default', v_fuel_savings_default,
      'annual_fuel_savings_max', v_fuel_savings_max,
      'annual_tire_savings', v_tire_savings,
      'annual_total_savings', v_total_savings,
      'roi_percent', v_roi,
      'payback_months', v_payback
    ),
    'blocking_configuration', to_jsonb(v_blockers),
    'warnings', to_jsonb(v_warnings)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_proposal_pipeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_enrichment_status text;
begin
  select enrichment_status
    into v_enrichment_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_enrichment_status, 'pending') = 'enriched' then
    insert into public.render_jobs (
      proposal_id, status, renderer, input
    )
    values (
      new.id,
      'pending',
      'html_pdf',
      jsonb_build_object('proposal_id', new.id, 'reason', 'company_already_enriched')
    );

    update public.proposals
    set status = 'rendering',
        updated_at = now()
    where id = new.id;
  else
    insert into public.enrichment_jobs (
      company_id, proposal_id, status, input
    )
    values (
      new.company_id,
      new.id,
      'pending',
      jsonb_build_object(
        'company_name', new.company_name_input,
        'proposal_id', new.id
      )
    );

    insert into public.render_jobs (
      proposal_id, status, renderer, input
    )
    values (
      new.id,
      'waiting',
      'html_pdf',
      jsonb_build_object('proposal_id', new.id, 'waiting_for', 'company_enrichment')
    );

    update public.proposals
    set status = 'enriching',
        updated_at = now()
    where id = new.id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_brand_asset_v1(p_asset_id uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_status text;
begin
  update public.company_brand_assets
  set
    status = case when attempts >= 3 then 'failed' else 'pending_copy' end,
    error_message = left(coalesce(p_error, 'unknown error'), 4000),
    locked_by = null,
    locked_until = null,
    updated_at = now()
  where id = p_asset_id
  returning status into v_status;

  if v_status is null then
    raise exception 'brand asset not found: %', p_asset_id;
  end if;

  return jsonb_build_object(
    'asset_id', p_asset_id,
    'status', v_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_sector_v1(p_sector_raw text, p_subsectors text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_input text;
  v_code text;
  v_name text;
  v_score numeric := 0;
begin
  v_input := lower(
    coalesce(p_sector_raw, '') || ' ' ||
    coalesce(array_to_string(p_subsectors, ' '), '')
  );

  select st.code, st.name,
         case
           when lower(coalesce(p_sector_raw,'')) = any(st.aliases) then 1.0
           else 0.75
         end
    into v_code, v_name, v_score
  from public.sector_taxonomy st
  where st.active = true
    and st.code <> 'other'
    and exists (
      select 1
      from unnest(st.aliases) a
      where v_input like '%' || lower(a) || '%'
    )
  order by
    case when lower(coalesce(p_sector_raw,'')) = any(st.aliases) then 1 else 0 end desc,
    st.priority desc
  limit 1;

  if v_code is null then
    v_code := 'other';
    v_name := 'Outros';
    v_score := 0.30;
  end if;

  return jsonb_build_object(
    'code', v_code,
    'name', v_name,
    'score', v_score,
    'raw', p_sector_raw,
    'subsectors', coalesce(to_jsonb(p_subsectors), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_sales_execution_result_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_external_id text := nullif(trim(p_command->>'externalId'),'');
  v_company_id uuid := nullif(p_command->>'companyId','')::uuid;
  v_contact_id uuid := nullif(p_command->>'contactId','')::uuid;
  v_session_id uuid := nullif(p_command->>'sessionId','')::uuid;
  v_member_id uuid := nullif(p_command->>'memberId','')::uuid;
  v_opportunity_id uuid := nullif(p_command->>'opportunityId','')::uuid;
  v_outcome text := upper(nullif(trim(p_command->>'result'),''));
  v_note text := nullif(left(trim(coalesce(p_command->>'note','')),2000),'');
  v_next_action_type text := upper(nullif(trim(p_command->>'nextActionType'),''));
  v_next_action_at timestamptz := nullif(p_command->>'nextActionAt','')::timestamptz;
  v_stage text;
  v_current_stage text;
  v_effective_stage text;
  v_attempt public.call_attempts%rowtype;
  v_activity_id uuid;
  v_meeting_id uuid;
  v_next_member_id uuid;
  v_meeting jsonb := coalesce(p_command->'meeting','{}'::jsonb);
  v_meeting_mode text := upper(nullif(trim(p_command->'meeting'->>'mode'),''));
  v_meeting_duration int := coalesce(nullif(p_command->'meeting'->>'durationMinutes','')::int,30);
begin
  if v_external_id is null or v_company_id is null then
    raise exception 'externalId and companyId are required';
  end if;

  if v_outcome not in ('NO_ANSWER','INVALID_NUMBER','GATEKEEPER','DECISION_MAKER_IDENTIFIED','DECISION_MAKER_REACHED','RETURN_LATER','QUALIFIED','MEETING_BOOKED','SEND_MATERIAL','PROPOSAL','NOT_INTERESTED') then
    raise exception 'invalid call result';
  end if;

  if v_outcome='MEETING_BOOKED' then
    if nullif(v_meeting->>'scheduledAt','') is null then raise exception 'meeting.scheduledAt required for MEETING_BOOKED'; end if;
    if v_meeting_mode not in ('ONLINE','PRESENCIAL','PHONE') then raise exception 'meeting.mode required for MEETING_BOOKED'; end if;
    if v_meeting_duration < 5 or v_meeting_duration > 480 then raise exception 'meeting.durationMinutes out of range'; end if;
  end if;

  insert into public.call_attempts(
    session_id,list_member_id,company_id,contact_id,ended_at,outcome,
    connected,decision_maker_reached,qualified,notes,metadata,external_id
  )
  values(
    v_session_id,v_member_id,v_company_id,v_contact_id,now(),v_outcome,
    v_outcome in ('GATEKEEPER','DECISION_MAKER_IDENTIFIED','DECISION_MAKER_REACHED','QUALIFIED','MEETING_BOOKED','SEND_MATERIAL','PROPOSAL'),
    v_outcome in ('DECISION_MAKER_REACHED','QUALIFIED','MEETING_BOOKED','PROPOSAL'),
    v_outcome in ('QUALIFIED','MEETING_BOOKED','PROPOSAL'),
    v_note,jsonb_build_object('source','dutra_os','command','record_sales_execution_result_v1'),v_external_id
  )
  on conflict (external_id) do nothing
  returning * into v_attempt;

  if v_attempt.id is null then
    select * into v_attempt from public.call_attempts where external_id=v_external_id limit 1;
    return jsonb_build_object('duplicate',true,'callAttemptId',v_attempt.id,'outcome',v_attempt.outcome);
  end if;

  v_stage := case v_outcome
    when 'NO_ANSWER' then 'CONTACT_ATTEMPTED'
    when 'INVALID_NUMBER' then 'CONTACT_ATTEMPTED'
    when 'GATEKEEPER' then 'CONNECTED'
    when 'DECISION_MAKER_IDENTIFIED' then 'DECISION_MAKER_IDENTIFIED'
    when 'DECISION_MAKER_REACHED' then 'DECISION_MAKER_CONTACTED'
    when 'RETURN_LATER' then 'CONNECTED'
    when 'QUALIFIED' then 'QUALIFIED'
    when 'MEETING_BOOKED' then 'MEETING_SCHEDULED'
    when 'SEND_MATERIAL' then 'CONNECTED'
    when 'PROPOSAL' then 'PROPOSAL'
    when 'NOT_INTERESTED' then 'LOST'
  end;

  if v_contact_id is not null and v_outcome='GATEKEEPER' then
    update public.crm_contacts
      set decision_level='gatekeeper', updated_at=now()
      where id=v_contact_id and (decision_level='unknown' or decision_level is null);
  elsif v_contact_id is not null and v_outcome in ('DECISION_MAKER_REACHED','QUALIFIED','MEETING_BOOKED','PROPOSAL') then
    update public.crm_contacts
      set decision_level='decision_maker', updated_at=now()
      where id=v_contact_id;
  end if;

  if v_opportunity_id is null then
    select id into v_opportunity_id
    from public.sales_opportunities
    where company_id=v_company_id
      and pipeline_stage not in ('WON','LOST')
    order by updated_at desc
    limit 1;
  end if;

  if v_opportunity_id is null then
    insert into public.sales_opportunities(
      company_id,primary_contact_id,source,stage,pipeline_stage,next_action_type,next_action_due_at,notes,metadata
    )
    values(
      v_company_id,v_contact_id,'prospecting','lead','PROSPECT',v_next_action_type,v_next_action_at,v_note,
      jsonb_build_object('source','dutra_os','created_by_command','record_sales_execution_result_v1')
    )
    returning id,pipeline_stage into v_opportunity_id,v_current_stage;
  else
    select pipeline_stage into v_current_stage
    from public.sales_opportunities
    where id=v_opportunity_id and company_id=v_company_id;
    if v_current_stage is null then raise exception 'opportunity does not belong to company'; end if;
  end if;

  v_effective_stage := v_current_stage;
  if v_outcome='NOT_INTERESTED' then
    v_effective_stage := 'LOST';
  elsif
    (case v_stage
      when 'PROSPECT' then 0 when 'CONTACT_ATTEMPTED' then 1 when 'CONNECTED' then 2
      when 'DECISION_MAKER_IDENTIFIED' then 3 when 'DECISION_MAKER_CONTACTED' then 4
      when 'QUALIFIED' then 5 when 'MEETING_TO_SCHEDULE' then 6 when 'MEETING_SCHEDULED' then 7
      when 'MEETING_COMPLETED' then 8 when 'PROPOSAL' then 9 when 'NEGOTIATION' then 10
      when 'WON' then 11 when 'LOST' then 12 else -1 end)
    >
    (case v_current_stage
      when 'PROSPECT' then 0 when 'CONTACT_ATTEMPTED' then 1 when 'CONNECTED' then 2
      when 'DECISION_MAKER_IDENTIFIED' then 3 when 'DECISION_MAKER_CONTACTED' then 4
      when 'QUALIFIED' then 5 when 'MEETING_TO_SCHEDULE' then 6 when 'MEETING_SCHEDULED' then 7
      when 'MEETING_COMPLETED' then 8 when 'PROPOSAL' then 9 when 'NEGOTIATION' then 10
      when 'WON' then 11 when 'LOST' then 12 else -1 end)
  then
    v_effective_stage := v_stage;
  end if;

  update public.sales_opportunities
  set pipeline_stage=v_effective_stage,
      stage=case
        when v_effective_stage='QUALIFIED' then 'qualified'
        when v_effective_stage in ('MEETING_TO_SCHEDULE','MEETING_SCHEDULED','MEETING_COMPLETED') then 'discovery'
        when v_effective_stage='PROPOSAL' then 'proposal'
        when v_effective_stage='NEGOTIATION' then 'negotiation'
        when v_effective_stage='WON' then 'won'
        when v_effective_stage='LOST' then 'lost'
        else stage
      end,
      primary_contact_id=coalesce(v_contact_id,primary_contact_id),
      next_action_type=coalesce(v_next_action_type,next_action_type),
      next_action_due_at=coalesce(v_next_action_at,next_action_due_at),
      updated_at=now()
  where id=v_opportunity_id and company_id=v_company_id;

  insert into public.crm_activities(
    company_id,contact_id,opportunity_id,activity_type,status,title,description,completed_at,metadata,external_id
  )
  values(
    v_company_id,v_contact_id,v_opportunity_id,'call','completed','Ligação · '||v_outcome,v_note,now(),
    jsonb_build_object('outcome',v_outcome,'call_attempt_id',v_attempt.id),v_external_id||':activity'
  )
  returning id into v_activity_id;

  if v_outcome='MEETING_BOOKED' then
    insert into public.meetings(
      company_id,opportunity_id,primary_contact_id,seller_id,meeting_status,meeting_type,mode,
      scheduled_at,duration_minutes,objective,notes,metadata,external_id
    )
    values(
      v_company_id,v_opportunity_id,v_contact_id,nullif(v_meeting->>'sellerId','')::uuid,
      'MEETING_SCHEDULED',nullif(v_meeting->>'type',''),v_meeting_mode,
      (v_meeting->>'scheduledAt')::timestamptz,v_meeting_duration,
      nullif(v_meeting->>'objective',''),nullif(v_meeting->>'notes',''),
      jsonb_build_object('source','dutra_os','call_attempt_id',v_attempt.id),v_external_id||':meeting'
    )
    returning id into v_meeting_id;
  end if;

  if v_member_id is not null then
    update public.lead_list_members
      set work_status='WORKED',last_attempt_at=now(),worked_at=now(),updated_at=now()
      where id=v_member_id and company_id=v_company_id;
  end if;

  if v_session_id is not null then
    select lm.id into v_next_member_id
    from public.lead_list_members lm
    join public.prospecting_sessions ps on ps.list_id=lm.list_id
    where ps.id=v_session_id
      and lm.work_status in ('AVAILABLE','IN_PROGRESS')
    order by lm.position asc nulls last,lm.created_at asc
    limit 1;

    update public.prospecting_sessions
      set current_member_id=v_next_member_id,updated_at=now()
      where id=v_session_id;
  end if;

  return jsonb_build_object(
    'duplicate',false,
    'callAttemptId',v_attempt.id,
    'activityId',v_activity_id,
    'opportunityId',v_opportunity_id,
    'meetingId',v_meeting_id,
    'pipelineStage',v_effective_stage,
    'nextMemberId',v_next_member_id
  );
end $function$

CREATE OR REPLACE FUNCTION public.resolve_design_tokens_v1(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_company public.companies%rowtype;
  v_brand jsonb;
  v_theme jsonb;
  v_colors jsonb;
  v_primary text;
  v_secondary text;
  v_accent text;
  v_background text;
  v_text text;
  v_source text;
begin
  select * into v_company
  from public.companies
  where id = p_company_id;

  if not found then
    raise exception 'company not found: %', p_company_id;
  end if;

  select metadata
  into v_brand
  from public.company_brand_assets
  where company_id = p_company_id
    and asset_type = 'brand_palette'
    and is_primary = true
    and status = 'stored'
  order by confidence desc nulls last, created_at desc
  limit 1;

  select visual_theme
  into v_theme
  from public.sector_assets
  where sector = coalesce(v_company.sector, 'other')
    and active = true
  limit 1;

  if v_theme is null then
    select visual_theme into v_theme
    from public.sector_assets
    where sector = 'other'
    limit 1;
  end if;

  v_colors := coalesce(v_brand->'colors', '{}'::jsonb);

  v_primary := coalesce(v_colors->>'primary', v_theme->>'primary', '#252525');
  v_secondary := coalesce(v_colors->>'secondary', v_theme->>'secondary', '#5D5D5D');
  v_accent := coalesce(v_colors->>'accent', v_theme->>'accent', '#B9974A');
  v_background := coalesce(v_colors->>'background', v_theme->>'background', '#F5F5F5');
  v_text := coalesce(v_colors->>'textPrimary', v_colors->>'text', v_theme->>'text', '#181818');

  if v_primary !~ '^#[0-9A-Fa-f]{6}$' then v_primary := v_theme->>'primary'; end if;
  if v_secondary !~ '^#[0-9A-Fa-f]{6}$' then v_secondary := v_theme->>'secondary'; end if;
  if v_accent !~ '^#[0-9A-Fa-f]{6}$' then v_accent := v_theme->>'accent'; end if;
  if v_background !~ '^#[0-9A-Fa-f]{6}$' then v_background := v_theme->>'background'; end if;
  if v_text !~ '^#[0-9A-Fa-f]{6}$' then v_text := v_theme->>'text'; end if;

  v_source := case when v_brand is not null then 'company_brand' else 'sector_fallback' end;

  return jsonb_build_object(
    'primary', coalesce(v_primary, '#252525'),
    'secondary', coalesce(v_secondary, '#5D5D5D'),
    'accent', coalesce(v_accent, '#B9974A'),
    'background', coalesce(v_background, '#F5F5F5'),
    'text', coalesce(v_text, '#181818'),
    'source', v_source,
    'sector', coalesce(v_company.sector, 'other')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.system_health_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_profile public.vehicle_profiles%rowtype;
  v_fin public.financial_parameter_sets%rowtype;
  v_ready_refs integer;
  v_pending_ref_approvals integer;
  v_visual_assets integer;
  v_pending_enrichment integer;
  v_pending_render integer;
  v_failed_jobs integer;
  v_warnings jsonb := '[]'::jsonb;
  v_score integer := 100;
begin
  select * into v_profile
  from public.vehicle_profiles
  where code = 'rodotrem_9_eixos'
  limit 1;

  select * into v_fin
  from public.financial_parameter_sets
  where active = true
  order by valid_from desc, created_at desc
  limit 1;

  select count(*) into v_ready_refs
  from public.reference_clients
  where active = true
    and approved_for_marketing = true
    and approval_status = 'approved';

  select count(*) into v_pending_ref_approvals
  from public.reference_clients
  where active = true
    and relationship_status in ('confirmed_client','former_client')
    and approval_status = 'pending';

  select count(*) into v_visual_assets
  from public.visual_asset_library
  where active = true
    and approved_for_commercial_use = true;

  select count(*) into v_pending_enrichment
  from public.enrichment_jobs
  where status in ('pending','processing','needs_review');

  select count(*) into v_pending_render
  from public.render_jobs
  where status in ('waiting','pending','processing');

  select
    (select count(*) from public.enrichment_jobs where status = 'failed')
    +
    (select count(*) from public.render_jobs where status = 'failed')
    +
    (select count(*) from public.company_brand_assets where status = 'failed')
  into v_failed_jobs;

  if v_profile.id is null then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object('code','vehicle_profile_missing','severity','critical','message','Perfil rodotrem_9_eixos não existe.')
    );
    v_score := v_score - 25;
  else
    if v_profile.supports_per_vehicle is null then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object('code','supports_per_vehicle_missing','severity','warning','message','Quantidade de suportes por veículo ainda não foi validada.')
      );
      v_score := v_score - 5;
    end if;
  end if;

  if v_fin.id is null then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object('code','financial_parameters_missing','severity','critical','message','Não existe conjunto financeiro ativo.')
    );
    v_score := v_score - 25;
  else
    if v_fin.package_price_per_vehicle is null then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object('code','package_price_missing','severity','critical','message','Preço do pacote por veículo não configurado.')
      );
      v_score := v_score - 20;
    end if;

    if v_fin.tire_price is null then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object('code','tire_price_missing','severity','warning','message','Preço médio de pneu não configurado.')
      );
      v_score := v_score - 10;
    end if;

    if v_fin.diesel_price is null then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object('code','diesel_base_missing','severity','info','message','Sem base padrão de diesel; ROI de combustível depende de dado do cliente.')
      );
      v_score := v_score - 2;
    end if;
  end if;

  if v_ready_refs = 0 then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code','reference_clients_empty',
        'severity','warning',
        'message','Nenhum cliente de referência está aprovado para prova social.',
        'confirmed_clients_pending_approval', v_pending_ref_approvals
      )
    );
    v_score := v_score - 8;
  end if;

  if v_visual_assets = 0 then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object('code','licensed_visual_assets_empty','severity','warning','message','Biblioteca de fotos comerciais licenciadas ainda está vazia; renderer usará layout sem foto.')
    );
    v_score := v_score - 8;
  end if;

  if v_failed_jobs > 0 then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object('code','failed_jobs_present','severity','warning','message','Existem jobs com falha que precisam de inspeção.','count',v_failed_jobs)
    );
    v_score := v_score - least(10, v_failed_jobs);
  end if;

  v_score := greatest(0, least(100, v_score));

  return jsonb_build_object(
    'status',
      case
        when v_score >= 90 then 'production_ready_core'
        when v_score >= 75 then 'mvp_ready_with_warnings'
        when v_score >= 50 then 'development_ready'
        else 'blocked'
      end,
    'readiness_score', v_score,
    'core', jsonb_build_object(
      'vehicle_profile_ready', v_profile.id is not null,
      'financial_parameters_ready', v_fin.id is not null,
      'package_price_per_vehicle', v_fin.package_price_per_vehicle,
      'tire_price', v_fin.tire_price,
      'diesel_price', v_fin.diesel_price,
      'approved_reference_clients', v_ready_refs,
      'confirmed_reference_clients_pending_approval', v_pending_ref_approvals,
      'approved_visual_assets', v_visual_assets
    ),
    'queue', jsonb_build_object(
      'pending_enrichment', v_pending_enrichment,
      'pending_render', v_pending_render,
      'failed_jobs', v_failed_jobs
    ),
    'warnings', v_warnings,
    'checked_at', now()
  );
end;
$function$
